const safeCode=s=>/^(?:\d{8}|\d{12}|\d{13}|\d{14})$/.test(String(s))&&!/^0+$/.test(String(s))&&validGTIN(String(s));
function validGTIN(s){let n=0;for(let i=s.length-2,w=3;i>=0;i--,w=4-w)n+=Number(s[i])*w;return (10-n%10)%10===Number(s.at(-1));}
function loadStorage(key){try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[];}catch{return [];}}
function saveStorage(key,obj){try{localStorage.setItem(key,JSON.stringify(obj));return true;}catch{return false;}}
const state={lang:(()=>{try{const v=JSON.parse(localStorage.getItem('fs13:settings')||'{}').language;if(['en','el','fr','de','es','it'].includes(v))return v;}catch{}const c=String(navigator.language||'').slice(0,2).toLowerCase();return ['el','fr','de','es','it'].includes(c)?c:'en';})(),code:'',name:'',data:null,near:null,basket:loadStorage(BASKET_STORAGE).filter(x=>safeCode(x.barcode)&&Number.isInteger(x.quantity)&&x.quantity>=1&&x.quantity<=99).slice(0,20),notes:loadStorage(NOTES_STORAGE).filter(x=>safeCode(x.barcode)&&Object.hasOwn(STORES,x.store)&&typeof x.price==='number'&&x.price>0).slice(-300),pricing:new Map(),loading:false,basketLoading:false};
